// StayFit - Site-wide JavaScript
// Initializes global event listeners, modal confirm logic, and SignalR notifications.

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initModalConfirm();
        initAutoSubmit();
        initNotifications();
    });

    // --- Modal Confirm ---
    function initModalConfirm() {
        var modalEl = document.getElementById('modalConfirm');
        if (!modalEl) return;

        if (!window.bootstrap || !window.bootstrap.Modal) return;

        var bsModal = new bootstrap.Modal(modalEl);
        var confirmBtn = modalEl.querySelector('.modal-confirm-btn');
        var titleEl = modalEl.querySelector('.modal-title');
        var bodyEl = modalEl.querySelector('.modal-body p, .modal-body');
        var pendingForm = null;
        var pendingHref = null;

        document.addEventListener('click', function (e) {
            var target = e.target;
            while (target && target !== document.body) {
                if (target.hasAttribute('data-confirm-title')) {
                    var trigger = target;
                    e.preventDefault();
                    e.stopPropagation();

                    var title = trigger.getAttribute('data-confirm-title') || 'Підтвердження';
                    var message = trigger.getAttribute('data-confirm-message') || 'Ви впевнені?';
                    var btnText = trigger.getAttribute('data-confirm-btn') || 'Підтвердити';

                    if (titleEl) titleEl.textContent = title;
                    if (bodyEl) bodyEl.textContent = message;
                    if (confirmBtn) confirmBtn.textContent = btnText;

                    var form = trigger.closest('form');
                    if (trigger.tagName === 'A' && trigger.href) {
                        pendingHref = trigger.href;
                        pendingForm = null;
                    } else if (form) {
                        pendingForm = form;
                        pendingHref = null;
                    }

                    bsModal.show();
                    return;
                }
                target = target.parentNode;
            }
        });

        if (confirmBtn) {
            confirmBtn.addEventListener('click', function () {
                bsModal.hide();
                if (pendingForm) pendingForm.submit();
                else if (pendingHref) window.location.href = pendingHref;
                pendingForm = null;
                pendingHref = null;
            });
        }
    }

    // --- Auto Submit ---
    function initAutoSubmit() {
        var selects = document.querySelectorAll('select[data-auto-submit]');
        for (var i = 0; i < selects.length; i++) {
            selects[i].addEventListener('change', function () {
                var form = this.closest('form');
                if (form) form.submit();
            });
        }
    }

    // --- SignalR Notifications ---
    function initNotifications() {
        if (typeof signalR === 'undefined') return;

        var connection = new signalR.HubConnectionBuilder()
            .withUrl("/notificationHub")
            .withAutomaticReconnect()
            .build();

        connection.on("ReceiveNotification", function (notification) {
            addNotificationToList(notification);
            updateBadge(1);
            showToast(notification);
        });

        connection.start()['catch'](function (err) {
            console.error("SignalR Connection Error: ", err.toString());
        });

        fetchNotifications();

        var markAllBtn = document.getElementById('markAllReadBtn');
        if (markAllBtn) {
            markAllBtn.addEventListener('click', function() {
                fetch('/notifications/mark-all-as-read', { method: 'POST' })
                    .then(function(r) { if (r.ok) fetchNotifications(); });
            });
        }

        var clearAllBtn = document.getElementById('clearAllBtn');
        if (clearAllBtn) {
            clearAllBtn.addEventListener('click', function() {
                fetch('/notifications/clear-all', { method: 'POST' })
                    .then(function(r) { if (r.ok) fetchNotifications(); });
            });
        }
    }

    function fetchNotifications() {
        fetch('/notifications/unread')
            .then(function(response) { return response.json(); })
            .then(function(data) {
                var list = document.getElementById('notificationList');
                if (!list) return;

                list.innerHTML = '';
                if (data.length === 0) {
                    list.innerHTML = '<div class="text-center text-muted">Немає сповіщень</div>';
                    updateBadge(0, true);
                    toggleActionButtons(false);
                } else {
                    for (var i = 0; i < data.length; i++) {
                        addNotificationToList(data[i]);
                    }
                    updateBadge(data.length, true);
                    toggleActionButtons(true);
                }
            });
    }

    function addNotificationToList(n) {
        var list = document.getElementById('notificationList');
        if (!list) return;

        var emptyMsg = list.querySelector('.text-muted');
        if (emptyMsg) emptyMsg.remove();

        var item = document.createElement('div');
        item.className = 'notification-item mb-2 p-2 border-bottom';
        item.innerHTML = '<div class="d-flex justify-content-between">' +
                '<strong class="small">' + n.title + '</strong>' +
                '<span class="text-muted smaller">' + new Date(n.createdAt).toLocaleTimeString() + '</span>' +
            '</div>' +
            '<div class="smaller">' + n.message + '</div>';
        
        list.insertBefore(item, list.firstChild);
        toggleActionButtons(true);
    }

    function updateBadge(count, isAbsolute) {
        var badge = document.getElementById('notificationBadge');
        var countEl = document.getElementById('notificationCount');
        if (!badge || !countEl) return;

        var current = isAbsolute ? 0 : parseInt(countEl.textContent) || 0;
        var total = current + count;

        countEl.textContent = total;
        if (total > 0) {
            badge.classList.remove('d-none');
        } else {
            badge.classList.add('d-none');
        }
    }

    function toggleActionButtons(show) {
        var btns = ['markAllReadBtn', 'clearAllBtn'];
        for (var i = 0; i < btns.length; i++) {
            var el = document.getElementById(btns[i]);
            if (el) {
                if (show) el.classList.remove('d-none');
                else el.classList.add('d-none');
            }
        }
    }

    function showToast(n) {
        console.log("New Notification:", n.title, n.message);
    }
})();

// --- Theme Toggle ---
function sfToggleTheme() {
    var html = document.documentElement;
    var isDark = html.getAttribute('data-bs-theme') === 'dark';
    var next = isDark ? 'light' : 'dark';
    html.setAttribute('data-bs-theme', next);
    localStorage.setItem('sf-theme', next);
    var icon = document.getElementById('sf-theme-icon');
    if (icon) {
        icon.className = next === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-fill';
    }
}

// Sync icon on load
(function () {
    var t = document.documentElement.getAttribute('data-bs-theme');
    var icon = document.getElementById('sf-theme-icon');
    if (icon) icon.className = t === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-fill';
})();

// Diary Notes Handler
// Handles character counting and note saving for food logs

(function() {
    'use strict';

    // Character counter for notes
    var textareas = document.querySelectorAll('.note-textarea');
    for (var i = 0; i < textareas.length; i++) {
        textareas[i].addEventListener('input', function() {
            var logId = this.getAttribute('data-log-id');
            var charCount = document.getElementById('charcount_' + logId);
            if (charCount) {
                charCount.textContent = this.value.length;
            }
        });
    }

    // Save note button handler
    var buttons = document.querySelectorAll('.save-note-btn');
    for (var j = 0; j < buttons.length; j++) {
        buttons[j].addEventListener('click', function() {
            var self = this;
            var logId = self.getAttribute('data-log-id');
            var textarea = document.getElementById('note_' + logId);
            if (!textarea) {
                return;
            }

            var noteText = textarea.value;
            var originalButtonText = self.innerHTML;
            self.disabled = true;
            self.innerHTML = '<i class="bi bi-hourglass-split"></i> Збереження...';

            fetch(window.diaryUpdateUrl || '/Diary/UpdateFoodLogNote', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'X-Requested-With': 'XMLHttpRequest'
                },
                body: 'logId=' + encodeURIComponent(logId) + '&note=' + encodeURIComponent(noteText)
            })
            .then(function(response) {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(function(data) {
                if (data.success) {
                    self.innerHTML = '<i class="bi bi-check-circle"></i> Збережено!';
                    setTimeout(function() {
                        self.innerHTML = originalButtonText;
                        self.disabled = false;
                    }, 2000);
                } else {
                    throw new Error(data.error || 'Помилка при збереженні нотатки');
                }
            })
            .catch(function(error) {
                console.error('Error saving note:', error);
                self.innerHTML = '<i class="bi bi-exclamation-circle"></i> Помилка';
                self.classList.add('btn-danger');
                self.classList.remove('btn-outline-success');
                setTimeout(function() {
                    self.innerHTML = originalButtonText;
                    self.classList.remove('btn-danger');
                    self.classList.add('btn-outline-success');
                    self.disabled = false;
                }, 3000);
            });
        });
    }
})();

(function () {
    var STORAGE_KEY = 'sf_water_' + new Date().toISOString().slice(0, 10);
    var GOAL = 8;

    function load() {
        return parseInt(localStorage.getItem(STORAGE_KEY) || '0', 10);
    }

    function save(val) {
        localStorage.setItem(STORAGE_KEY, val);
    }

    function render(count) {
        var intake = document.getElementById('waterIntake');
        var dropsContainer = document.getElementById('waterDrops');
        if (!dropsContainer) return;

        var card = dropsContainer.closest('.card');
        var bar = card ? card.querySelector('.sf-progress-bar') : null;
        
        if (intake) intake.textContent = count;
        if (bar)    bar.style.width = Math.min(count / GOAL * 100, 100) + '%';
        
        dropsContainer.innerHTML = '';
        for (var i = 1; i <= GOAL; i++) {
            (function(idx) {
                var span = document.createElement('span');
                span.className = 'sf-drop' + (idx <= count ? ' active' : '');
                span.textContent = '○';
                span.title = idx + ' склянка';
                span.addEventListener('click', function () {
                    var cur = load();
                    var newVal = (idx <= cur && idx === cur) ? cur - 1 : idx;
                    save(newVal < 0 ? 0 : newVal);
                    render(load());
                });
                dropsContainer.appendChild(span);
            })(i);
        }
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (!document.getElementById('waterDrops')) return;
        
        render(load());
        var resetBtn = document.getElementById('waterResetBtn');
        if (resetBtn) resetBtn.addEventListener('click', function () {
            save(0); render(0);
        });
    });
})();

(function () {
    var STORAGE_KEY = 'sf_water_' + new Date().toISOString().slice(0, 10);
    var HISTORY_KEY = 'sf_water_history_' + new Date().toISOString().slice(0, 10);
    var GOAL = 8;

    function load() {
        return parseInt(localStorage.getItem(STORAGE_KEY) || '0', 10);
    }

    function save(val) {
        localStorage.setItem(STORAGE_KEY, Math.max(0, val));
    }

    function getHistory() {
        try {
            return JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
        } catch(e) {
            return [];
        }
    }

    function saveHistory(entries) {
        localStorage.setItem(HISTORY_KEY, JSON.stringify(entries));
    }

    function addToHistory(glasses) {
        var history = getHistory();
        history.push({
            time: new Date().toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' }),
            glasses: glasses
        });
        saveHistory(history);
    }

    function render(count) {
        var intake = document.getElementById('waterIntake');
        var drops = document.getElementById('waterDrops');
        var progressBar = document.querySelector('.sf-progress-bar');

        if (intake) intake.textContent = count;
        if (!drops) return;

        if (progressBar) {
            progressBar.classList.add('pulse');
            setTimeout(function() { progressBar.classList.remove('pulse'); }, 800);
        }

        drops.innerHTML = '';
        for (var i = 1; i <= GOAL; i++) {
            (function(idx) {
                var span = document.createElement('span');
                span.className = 'sf-drop' + (idx <= count ? ' active' : '');
                span.textContent = '💧';
                span.title = idx + ' склянка';
                span.style.cursor = 'pointer';
                span.addEventListener('click', function () {
                    var cur = load();
                    var newVal = (idx <= cur && idx === cur) ? cur - 1 : idx;
                    var finalValue = Math.max(0, newVal);
                    var diff = finalValue - cur;
                    save(finalValue);
                    if (diff > 0) addToHistory(diff);
                    render(finalValue);
                    updateHistory();
                    updateProgressBar(finalValue);
                });
                drops.appendChild(span);
            })(i);
        }
    }

    function updateProgressBar(count) {
        var pct = count / GOAL * 100;
        var displayPct = Math.min(pct, 100);
        var bar = document.querySelector('.sf-progress-bar');
        if (bar) {
            bar.style.width = displayPct + '%';
            bar.className = count > GOAL ? 'sf-progress-bar bg-danger' : 'sf-progress-bar bg-info';
        }
        var label = document.querySelector('.sf-progress-pct');
        if (label) label.textContent = displayPct.toFixed(0) + '%';
        var warning = document.getElementById('waterWarning');
        if (warning) warning.style.display = count > GOAL ? 'block' : 'none';
    }

    function updateHistory() {
        var history = getHistory();
        var container = document.getElementById('waterHistory');
        if (!container) return;
        
        if (history.length === 0) {
            container.innerHTML = '<div class="list-group-item text-muted text-center py-4">Поки немає записів. Почніть додавати воду!</div>';
            return;
        }

        var html = '';
        for (var i = 0; i < history.length; i++) {
            var entry = history[i];
            var label = entry.glasses === 1 ? 'склянка' : 'склянок';
            html += '<div class="list-group-item d-flex justify-content-between align-items-center">' +
                '<div>' +
                    '<span class="fw-semibold">' + entry.time + '</span>' +
                    '<span class="badge bg-info ms-2">' + entry.glasses + ' ' + label + '</span>' +
                '</div>' +
                '<button class="btn btn-sm btn-outline-danger" onclick="removeHistoryEntry(' + i + ')">' +
                    '✕' +
                '</button>' +
            '</div>';
        }
        container.innerHTML = html;
    }

    window.removeHistoryEntry = function(idx) {
        var history = getHistory();
        if (idx < 0 || idx >= history.length) return;
        history.splice(idx, 1);
        saveHistory(history);
        updateHistory();
        var total = 0;
        for (var i = 0; i < history.length; i++) {
            total += history[i].glasses;
        }
        save(total);
        render(total);
        updateProgressBar(total);
    };

    document.addEventListener('DOMContentLoaded', function () {
        if (!document.getElementById('waterHistory')) return;

        var count = load();
        render(count);
        updateHistory();
        updateProgressBar(count);

        var buttons = document.querySelectorAll('.water-btn');
        for (var i = 0; i < buttons.length; i++) {
            buttons[i].addEventListener('click', function () {
                var self = this;
                var glasses = parseInt(self.getAttribute('data-glasses'), 10);
                var cur = load();
                var newVal = cur + glasses;
                save(newVal);
                addToHistory(glasses);
                render(newVal);
                updateHistory();
                updateProgressBar(newVal);
                
                self.classList.add('active');
                setTimeout(function() { self.classList.remove('active'); }, 200);
            });
        }

        var resetBtn = document.getElementById('waterResetBtn');
        if (resetBtn) {
            resetBtn.addEventListener('click', function () {
                if (confirm('Ви впевнені? Це скине всі записи на сьогодні.')) {
                    save(0);
                    localStorage.removeItem(HISTORY_KEY);
                    render(0);
                    updateHistory();
                    updateProgressBar(0);
                }
            });
        }
    });
})();

document.addEventListener('DOMContentLoaded', function () {
    var canvas = document.getElementById('progressChart');
    if (!canvas) return;

    var ctx = canvas.getContext('2d');
    
    try {
        var labels = JSON.parse(canvas.getAttribute('data-labels') || '[]');
        var caloriesData = JSON.parse(canvas.getAttribute('data-calories') || '[]');
        var goalValue = parseFloat(canvas.getAttribute('data-goal') || '0');
        var totalDays = parseInt(canvas.getAttribute('data-days') || '0');
        
        var goalLine = [];
        for (var i = 0; i < labels.length; i++) {
            goalLine.push(goalValue);
        }

        new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Спожито калорій',
                        data: caloriesData,
                        backgroundColor: 'rgba(54, 162, 235, 0.6)',
                        borderColor: 'rgba(54, 162, 235, 1)',
                        borderWidth: 1
                    },
                    {
                        label: 'Ціль калорій',
                        data: goalLine,
                        type: 'line',
                        backgroundColor: 'rgba(255, 99, 132, 1)',
                        borderColor: 'rgba(255, 99, 132, 1)',
                        borderWidth: 2,
                        fill: false,
                        pointRadius: 0
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    } catch (e) {
        console.error('Failed to parse chart data', e);
    }
});

(function () {
    var MAX_SUBJECT = 200;
    var MAX_BODY = 5000;

    var emailTemplates = {
        welcome: {
            subject: 'Добро пожалувати до StayFit!',
            body: '<p>Привіт!</p><p>Благодарим за реєстрацію в <b>StayFit</b> — програмі для контролю харчування та здорового способу життя.</p><p>Почніть з встановлення своїх цілей харчування і слідкуйте за прогресом кожного дня.</p><p><a href="https://stayfit.com/nutrition-goal" style="color: #007bff; text-decoration: none;">Встановити цілі</a></p>'
        },
        update: {
            subject: 'Нове оновлення системи',
            body: '<p>Привіт!</p><p>Ми щойно оновили <b>StayFit</b> з новими функціями:</p><ul><li>Новий інтерфейс відстеження води</li><li>Покращена статистика</li><li>Виправлення помилок</li></ul><p>Дякуємо за використання нашого сервісу!</p>'
        },
        maintenance: {
            subject: 'Планове технічне обслуговування',
            body: '<p>Привіт!</p><p>20 травня 2026 року з 22:00 до 23:00 (UTC) буде проведено планове технічне обслуговування серверів.</p><p>Під час цього часу сервіс може бути недоступний.</p><p>Вибачаємо за незручності!</p>'
        }
    };

    function showMessage(message, type) {
        var msgDiv = document.getElementById('formMessage');
        if (!msgDiv) return;
        msgDiv.className = 'alert alert-' + type;
        msgDiv.textContent = message;
        msgDiv.style.display = 'block';
    }

    function init() {
        var subjectInput = document.getElementById('subject');
        var bodyInput = document.getElementById('htmlBody');
        var form = document.getElementById('broadcastForm');

        if (subjectInput) {
            subjectInput.addEventListener('input', function (e) {
                var count = e.target.value.length;
                var counter = document.getElementById('subjectCount');
                var progress = document.getElementById('subjectProgress');
                if (counter) counter.textContent = count + ' / ' + MAX_SUBJECT;
                if (progress) progress.style.width = (count / MAX_SUBJECT * 100) + '%';
            });
        }

        if (bodyInput) {
            bodyInput.addEventListener('input', function (e) {
                var count = e.target.value.length;
                var counter = document.getElementById('bodyCount');
                var progress = document.getElementById('bodyProgress');
                if (counter) counter.textContent = count + ' / ' + MAX_BODY;
                if (progress) progress.style.width = (count / MAX_BODY * 100) + '%';
            });
        }

        if (form) {
            form.addEventListener('submit', function (e) {
                e.preventDefault();

                var subject = document.getElementById('subject').value.trim();
                var htmlBody = document.getElementById('htmlBody').value.trim();

                if (!subject || !htmlBody) {
                    showMessage('Заповніть усі поля', 'warning');
                    return;
                }

                var sendBtn = document.getElementById('sendBtn');
                sendBtn.disabled = true;
                sendBtn.innerHTML = 'Відправлення...';

                fetch('/admin/email/send', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ subject: subject, htmlBody: htmlBody })
                })
                .then(function(response) {
                    return response.json().then(function(data) {
                        if (response.ok) {
                            showMessage(data.message, 'success');
                            form.reset();
                            document.getElementById('subjectCount').textContent = '0 / 200';
                            document.getElementById('bodyCount').textContent = '0 / 5000';
                            document.getElementById('subjectProgress').style.width = '0%';
                            document.getElementById('bodyProgress').style.width = '0%';
                            setTimeout(function() { location.reload(); }, 2000);
                        } else {
                            showMessage(data.message, 'danger');
                        }
                    });
                })
                ['catch'](function(error) {
                    showMessage('Помилка: ' + error.message, 'danger');
                })
                ['finally'](function() {
                    sendBtn.disabled = false;
                    sendBtn.innerHTML = 'Відправити';
                });
            });
        }

        // Global functions for buttons
        window.loadTemplate = function(templateName) {
            var template = emailTemplates[templateName];
            if (template) {
                var s = document.getElementById('subject');
                var b = document.getElementById('htmlBody');
                if (s) s.value = template.subject;
                if (b) b.value = template.body;
                if (s) s.dispatchEvent(new Event('input'));
                if (b) b.dispatchEvent(new Event('input'));
                showMessage('Шаблон завантажено', 'info');
            }
        };

        window.viewBroadcast = function(subject, htmlBody) {
            var ps = document.getElementById('previewSubject');
            var pb = document.getElementById('previewBody');
            if (ps) ps.textContent = subject;
            if (pb) pb.innerHTML = decodeURIComponent(htmlBody);
            var modalEl = document.getElementById('previewModal');
            if (modalEl && window.bootstrap && window.bootstrap.Modal) {
                var modal = new bootstrap.Modal(modalEl);
                modal.show();
            }
        };

        var previewBtn = document.querySelector('[data-bs-target="#previewModal"]');
        if (previewBtn) {
            previewBtn.addEventListener('click', function() {
                var subject = document.getElementById('subject').value.trim();
                var htmlBody = document.getElementById('htmlBody').value.trim();
                
                if (!subject || !htmlBody) {
                    showMessage('Заповніть тему та текст листа для перегляду', 'warning');
                    return false;
                }
                
                var ps = document.getElementById('previewSubject');
                var pb = document.getElementById('previewBody');
                if (ps) ps.textContent = subject;
                if (pb) pb.innerHTML = htmlBody;
            });
        }
    }

    document.addEventListener('DOMContentLoaded', init);
})();

(function () {
    var form     = document.getElementById('sf-ps-form');
    var results  = document.getElementById('sf-ps-results');
    var skeleton = document.getElementById('sf-ps-skeleton');
    var btn      = document.getElementById('sf-ps-btn');

    if (!form) return;

    form.addEventListener('submit', function (e) {
        e.preventDefault();

        var action = form.getAttribute('action') || location.href;
        var query = "";
        var formData = new FormData(form);
        
        // Manual query string building for ES5 compatibility (avoiding URL object if possible)
        // or just use location.origin if URL is available (IE11 doesn't have it, but minifier might be the issue)
        var url = new URL(action, location.origin);
        url.searchParams.delete('page');
        
        // FormData.forEach is ES6
        var entries = formData.entries();
        var entry = entries.next();
        while (!entry.done) {
            var k = entry.value[0];
            var v = entry.value[1];
            if (v) url.searchParams.set(k, v);
            else   url.searchParams.delete(k);
            entry = entries.next();
        }

        if (results) results.classList.add('d-none');
        if (skeleton) skeleton.classList.remove('d-none');
        if (btn) btn.disabled = true;

        history.pushState(null, '', url.toString());

        fetch(url.toString(), { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
            .then(function(r) { return r.text(); })
            .then(function(html) {
                var parser = new DOMParser();
                var doc   = parser.parseFromString(html, 'text/html');
                var fresh = doc.getElementById('sf-ps-results');
                if (fresh && results) results.innerHTML = fresh.innerHTML;
            })
            ['catch'](function() { location.href = url.toString(); })
            ['finally'](function() {
                if (skeleton) skeleton.classList.add('d-none');
                if (results) results.classList.remove('d-none');
                if (btn) btn.disabled = false;
            });
    });
})();

(function () {
    'use strict';

    // --- SECURITY TAB ACTIVATION ---
    document.addEventListener('DOMContentLoaded', function() {
        var container = document.querySelector('[data-profile-security-active]');
        if (container && container.getAttribute('data-profile-security-active') === 'true') {
            var securityTab = document.getElementById('security-tab');
            if (securityTab && window.bootstrap && window.bootstrap.Tab) {
                var tab = new bootstrap.Tab(securityTab);
                tab.show();
            }
        }
    });

    // --- FORM VALIDATIONS ---
    document.addEventListener('DOMContentLoaded', function() {
        var changePasswordForm = document.querySelector('form[action="/account-security/change-password"]');
        if (changePasswordForm) {
            changePasswordForm.addEventListener('submit', function (e) {
                var newPassword = document.getElementById('newPassword').value;
                var confirmPassword = document.getElementById('confirmPassword').value;

                if (newPassword !== confirmPassword) {
                    e.preventDefault();
                    alert('Паролі не збігаються!');
                    return false;
                }
            });
        }

        var deleteForm = document.querySelector('form[action="/account-security/delete-account"]');
        if (deleteForm) {
            deleteForm.addEventListener('submit', function (e) {
                var password = document.getElementById('deletePassword').value;
                if (!password || password.trim() === '') {
                    e.preventDefault();
                    alert('Будь ласка, введіть пароль для підтвердження.');
                    return false;
                }
                
                if (!confirm('ОСТАННЄ ПОПЕРЕДЖЕННЯ! Ви дійсно хочете видалити акаунт назавжди?')) {
                    e.preventDefault();
                    return false;
                }
            });
        }
    });

    // --- SECURITY LOGS ---
    function loadSecurityLogs(page) {
        if (!page) page = 1;
        var container = document.getElementById('securityLogs');
        if (!container) return;

        var filterEl = document.getElementById('securityEventTypeFilter');
        var eventType = filterEl ? filterEl.value : '';
        var requestUrl = '/security-log/logs?page=' + page;

        if (eventType) {
            requestUrl += '&eventType=' + encodeURIComponent(eventType);
        }

        fetch(requestUrl)
            .then(function(response) {
                if (!response.ok) {
                    return response.json().then(function(errorPayload) {
                        throw new Error(errorPayload && errorPayload.message ? errorPayload.message : 'Помилка при завантаженні журналу');
                    })['catch'](function() {
                        throw new Error('Помилка при завантаженні журналу');
                    });
                }
                return response.json();
            })
            .then(function(data) {
                renderSecurityLogs(data);
            })
            ['catch'](function(error) {
                console.error('Помилка завантаження логів:', error);
                container.innerHTML = 
                    '<div class="alert alert-warning"><i class="bi bi-exclamation-triangle"></i> Не вдалося завантажити історію безпеки: ' + (error.message || 'невідома помилка') + '</div>';
            });
    }

    function renderSecurityLogs(pagedResult) {
        var container = document.getElementById('securityLogs');
        if (!container) return;

        if (!pagedResult || typeof pagedResult !== 'object') {
            container.innerHTML = '<div class="alert alert-warning"><i class="bi bi-exclamation-triangle"></i> Сервер повернув некоректні дані журналу безпеки.</div>';
            return;
        }

        var items = pagedResult.items || pagedResult.Items || [];
        var pageNumber = pagedResult.pageNumber || pagedResult.PageNumber || 1;
        var totalPages = pagedResult.totalPages || pagedResult.TotalPages || 1;
        var totalCount = pagedResult.totalCount || pagedResult.TotalCount || 0;
        
        if (!items.length) {
            container.innerHTML = '<p class="text-muted">Немає записів у журналі безпеки.</p>';
            return;
        }

        var html = '<div class="table-responsive">';
        html += '<table class="table table-sm table-hover align-middle mb-0">';
        html += '<thead class="table-light"><tr>';
        html += '<th>Дата/Час</th><th>Тип івенту</th><th>Опис</th><th>Пристрій</th><th>IP адреса</th><th>Статус</th>';
        html += '</tr></thead><tbody>';

        for (var i = 0; i < items.length; i++) {
            var log = items[i];
            var date = new Date(log.createdAt);
            var formattedDate = date.toLocaleDateString('uk-UA') + ' ' + date.toLocaleTimeString('uk-UA');
            var statusBadge = log.status === 'Success' 
                ? '<span class="badge bg-success"><i class="bi bi-check-lg"></i> Успіх</span>'
                : '<span class="badge bg-danger"><i class="bi bi-x-lg"></i> Помилка</span>';
            
            var eventBadge = '';
            switch(log.eventType) {
                case 'Login': eventBadge = '<span class="badge bg-info"><i class="bi bi-box-arrow-in-right"></i> Вхід</span>'; break;
                case 'Logout': eventBadge = '<span class="badge bg-secondary"><i class="bi bi-box-arrow-right"></i> Вихід</span>'; break;
                case 'PasswordChange': eventBadge = '<span class="badge bg-warning"><i class="bi bi-key"></i> Зміна пароля</span>'; break;
                case 'SessionTerminated': eventBadge = '<span class="badge bg-danger"><i class="bi bi-stop-circle"></i> Сеанс завершено</span>'; break;
                default: eventBadge = '<span class="badge bg-dark">' + log.eventType + '</span>';
            }
            
            html += '<tr>';
            html += '<td>' + formattedDate + '</td>';
            html += '<td>' + eventBadge + '</td>';
            html += '<td>' + log.description + '</td>';
            html += '<td>' + (log.deviceSummary || 'Unknown') + '</td>';
            html += '<td>' + (log.ipAddress || '—') + '</td>';
            html += '<td>' + statusBadge + '</td>';
            html += '</tr>';
        }

        html += '</tbody></table></div>';
        
        if (totalPages > 1) {
            html += '<p class="text-muted small mt-3">Сторінка ' + pageNumber + ' з ' + totalPages + 
                    ' (' + totalCount + ' записів)</p>';
        }
        
        container.innerHTML = html;
    }

    document.addEventListener('DOMContentLoaded', function() {
        var filter = document.getElementById('securityEventTypeFilter');
        if (filter) {
            filter.addEventListener('change', function() { loadSecurityLogs(1); });
        }
        if (document.getElementById('securityLogs')) {
            loadSecurityLogs(1);
        }
    });

    // --- METRICS & AUTO-SAVE ---
    document.addEventListener('DOMContentLoaded', function() {
        var inputIds = ['Weight', 'Height', 'DateOfBirth', 'Gender', 'ActivityLevel', 'FullName'];
        var elements = {};
        for (var i = 0; i < inputIds.length; i++) {
            var id = inputIds[i];
            var el = document.getElementById(id);
            if (el) elements[id] = el;
        }

        var bmiEl = document.getElementById('calc-bmi');
        var bmrEl = document.getElementById('calc-bmr');
        var tdeeEl = document.getElementById('calc-tdee');
        var saveIndicator = document.getElementById('auto-save-indicator');

        if (!bmiEl) return;

        function calculateMetrics() {
            var weight = parseFloat(elements.Weight ? elements.Weight.value : 0);
            var height = parseFloat(elements.Height ? elements.Height.value : 0);
            var gender = elements.Gender ? elements.Gender.value : null;
            var dob = elements.DateOfBirth ? elements.DateOfBirth.value : null;
            var activity = elements.ActivityLevel ? elements.ActivityLevel.value : null;

            if (!weight || !height) {
                if (bmiEl) bmiEl.innerText = '-';
                if (bmrEl) bmrEl.innerText = '- ккал';
                if (tdeeEl) tdeeEl.innerText = '- ккал';
                return;
            }

            var heightM = height / 100;
            var bmi = weight / (heightM * heightM);
            if (bmiEl) bmiEl.innerText = bmi.toFixed(1);

            var age = 30;
            if (dob) {
                var birthDate = new Date(dob);
                var today = new Date();
                age = today.getFullYear() - birthDate.getFullYear();
                var m = today.getMonth() - birthDate.getMonth();
                if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
                    age--;
                }
            }

            var bmr = 0;
            if (gender === 'Чоловік') {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) + 5;
            } else if (gender === 'Жінка') {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) - 161;
            } else {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) - 78;
            }
            if (bmrEl) bmrEl.innerText = Math.round(bmr) + ' ккал';

            var activityMultiplier = 1.2;
            switch(activity) {
                case 'LightlyActive': activityMultiplier = 1.375; break;
                case 'ModeratelyActive': activityMultiplier = 1.55; break;
                case 'VeryActive': activityMultiplier = 1.725; break;
                case 'SuperActive': activityMultiplier = 1.9; break;
            }

            var tdee = bmr * activityMultiplier;
            if (tdeeEl) tdeeEl.innerText = Math.round(tdee) + ' ккал';
        }

        var saveTimeout = null;

        function autoSave() {
            if (saveIndicator) {
                saveIndicator.innerText = "Зберігається...";
                saveIndicator.classList.remove('bg-success', 'd-none');
                saveIndicator.classList.add('bg-warning', 'text-dark');
            }

            var payload = {
                FullName: elements.FullName ? elements.FullName.value : '',
                Weight: parseFloat(elements.Weight ? elements.Weight.value : 0) || null,
                Height: parseFloat(elements.Height ? elements.Height.value : 0) || null,
                DateOfBirth: elements.DateOfBirth ? elements.DateOfBirth.value : null,
                Gender: elements.Gender ? elements.Gender.value : null,
                ActivityLevel: elements.ActivityLevel ? elements.ActivityLevel.value : null
            };

            var tokenEl = document.querySelector('input[name="__RequestVerificationToken"]');
            var token = tokenEl ? tokenEl.value : '';

            fetch('/profile/auto-save', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'RequestVerificationToken': token
                },
                body: JSON.stringify(payload)
            })
            .then(function(response) {
                if (response.ok) {
                    if (saveIndicator) {
                        saveIndicator.innerText = "Збережено ✔️";
                        saveIndicator.classList.remove('bg-warning', 'text-dark');
                        saveIndicator.classList.add('bg-success');
                        setTimeout(function() { saveIndicator.classList.add('d-none'); }, 3000);
                    }
                } else {
                    if (saveIndicator) {
                        saveIndicator.innerText = "Помилка";
                        saveIndicator.classList.remove('bg-warning', 'text-dark');
                        saveIndicator.classList.add('bg-danger');
                    }
                }
            })
            ['catch'](function(error) {
                console.error("Auto-save error", error);
                if (saveIndicator) {
                    saveIndicator.innerText = "Помилка";
                    saveIndicator.classList.remove('bg-warning', 'text-dark');
                    saveIndicator.classList.add('bg-danger');
                }
            });
        }

        for (var k = 0; k < inputIds.length; k++) {
            (function(id) {
                if (elements[id]) {
                    elements[id].addEventListener('input', function() {
                        calculateMetrics();
                        clearTimeout(saveTimeout);
                        saveTimeout = setTimeout(autoSave, 1500);
                    });
                }
            })(inputIds[k]);
        }

        calculateMetrics();
    });
})();

(function () {
    // --- LOGIN FORM ---
    var loginForm = document.getElementById('loginForm');
    if (loginForm) {
        var emailInput = document.getElementById('emailInput');
        var passwordInput = document.getElementById('passwordInput');
        var submitBtn = document.getElementById('submitBtn');
        var submitText = document.getElementById('submitText');
        var submitSpinner = document.getElementById('submitSpinner');
        var loginAlert = document.getElementById('loginAlert');
        var loginAlertText = document.getElementById('loginAlertText');
        var retryBtn = document.getElementById('retryBtn');

        var validateEmail = function(email) {
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
        };

        var checkValidity = function(element, validator) {
            if (element.value.trim() === '') {
                element.classList.remove('is-invalid', 'is-valid');
                return false;
            }
            var isValid = validator(element.value);
            if (isValid) {
                element.classList.remove('is-invalid');
                element.classList.add('is-valid');
            } else {
                element.classList.remove('is-valid');
                element.classList.add('is-invalid');
            }
            return isValid;
        };

        if (emailInput) {
            emailInput.addEventListener('input', function() {
                checkValidity(emailInput, validateEmail);
            });
        }
        if (passwordInput) {
            passwordInput.addEventListener('input', function() {
                checkValidity(passwordInput, function(val) { return val.length >= 8; });
            });
        }

        var submitLoginForm = function() {
            submitBtn.disabled = true;
            if (submitText) submitText.classList.add('opacity-0');
            if (submitSpinner) submitSpinner.classList.remove('d-none');
            if (loginAlert) loginAlert.classList.add('d-none');

            var formData = new FormData(loginForm);

            fetch(loginForm.action, {
                method: 'POST',
                body: formData,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            })
            .then(function(response) {
                if (response.redirected) {
                    submitBtn.classList.replace('btn-primary', 'btn-success');
                    if (submitSpinner) submitSpinner.classList.add('d-none');
                    if (submitText) {
                        submitText.innerHTML = '<i class="bi bi-check2-circle me-2"></i>Успішно';
                        submitText.classList.remove('opacity-0');
                    }
                    setTimeout(function() { window.location.href = response.url; }, 500);
                    return;
                }

                return response.text().then(function(html) {
                    var parser = new DOMParser();
                    var doc = parser.parseFromString(html, 'text/html');
                    var errors = doc.querySelector('.validation-summary-errors');
                    if (errors) {
                        if (loginAlertText) loginAlertText.textContent = errors.textContent.trim();
                        if (loginAlert) loginAlert.classList.remove('d-none');
                        emailInput.classList.add('is-invalid');
                        passwordInput.classList.add('is-invalid');
                    } else {
                        window.location.reload();
                    }
                });
            })
            ['catch'](function(error) {
                if (loginAlertText) loginAlertText.textContent = 'Помилка з\'єднання. Перевірте інтернет.';
                if (loginAlert) loginAlert.classList.remove('d-none');
            })
            ['finally'](function() {
                submitBtn.disabled = false;
                if (submitText) submitText.classList.remove('opacity-0');
                if (submitSpinner) submitSpinner.classList.add('d-none');
            });
        };

        loginForm.addEventListener('submit', function (e) {
            e.preventDefault();
            var isEmailValid = checkValidity(emailInput, validateEmail);
            var isPasswordValid = checkValidity(passwordInput, function(val) { return val.length >= 8; });
            if (!isEmailValid || !isPasswordValid) return;
            submitLoginForm();
        });

        if (retryBtn) {
            retryBtn.addEventListener('click', function() {
                loginAlert.classList.add('d-none');
                submitLoginForm();
            });
        }
    }

    // --- REGISTER FORM ---
    var regForm = document.getElementById('registerForm');
    if (regForm) {
        var passwordReg = document.getElementById('password');
        var confirmPasswordReg = document.getElementById('confirmPassword');
        var confirmErrorReg = document.getElementById('confirmPasswordError');

        var checkPasswordsReg = function() {
            if (confirmPasswordReg.value && passwordReg.value !== confirmPasswordReg.value) {
                confirmPasswordReg.classList.add('is-invalid');
                confirmErrorReg.textContent = "Паролі не співпадають";
                return false;
            } else if (confirmPasswordReg.value) {
                confirmPasswordReg.classList.replace('is-invalid', 'is-valid');
                confirmErrorReg.textContent = "";
                return true;
            }
            return true;
        };

        if (passwordReg) passwordReg.addEventListener('input', checkPasswordsReg);
        if (confirmPasswordReg) confirmPasswordReg.addEventListener('input', checkPasswordsReg);

        regForm.addEventListener('submit', function (e) {
            if (!regForm.checkValidity() || !checkPasswordsReg()) {
                e.preventDefault();
                e.stopPropagation();
                var elements = regForm.elements;
                for (var i = 0; i < elements.length; i++) {
                    if (!elements[i].checkValidity()) elements[i].classList.add('is-invalid');
                }
            } else {
                var btnReg = document.getElementById('submitBtn');
                if (btnReg) btnReg.disabled = true;
                var txtReg = document.getElementById('submitText');
                if (txtReg) txtReg.classList.add('opacity-0');
                var spnReg = document.getElementById('submitSpinner');
                if (spnReg) spnReg.classList.remove('d-none');
            }
            regForm.classList.add('was-validated');
        });
    }

    // --- FORGOT PASSWORD ---
    var forgotForm = document.getElementById('forgotForm');
    if (forgotForm) {
        var emailInputForgot = document.getElementById('emailInput');
        var submitBtnForgot = document.getElementById('submitBtn');
        var resendBtnForgot = document.getElementById('resendBtn');
        
        var submitForgot = function() {
            submitBtnForgot.disabled = true;
            var alertMsg = document.getElementById('alertMsg');
            if (alertMsg) alertMsg.classList.add('d-none');

            var formDataForgot = new FormData(forgotForm);

            fetch(forgotForm.action, {
                method: 'POST',
                body: formDataForgot,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            })
            .then(function(response) {
                if (response.ok || response.redirected) {
                    var step1 = document.getElementById('step1');
                    var step2 = document.getElementById('step2');
                    var sentEmail = document.getElementById('sentEmail');
                    if (step1) step1.classList.add('d-none');
                    if (step2) step2.classList.remove('d-none');
                    if (sentEmail) sentEmail.textContent = emailInputForgot.value;
                } else {
                    if (alertMsg) {
                        alertMsg.textContent = 'Не вдалося надіслати запит.';
                        alertMsg.classList.remove('d-none');
                    }
                }
            })
            ['catch'](function(err) {
                if (alertMsg) {
                    alertMsg.textContent = 'Помилка мережі.';
                    alertMsg.classList.remove('d-none');
                }
            })
            ['finally'](function() {
                submitBtnForgot.disabled = false;
            });
        };

        forgotForm.addEventListener('submit', function(e) {
            e.preventDefault();
            if (!emailInputForgot.value.trim() || !emailInputForgot.checkValidity()) {
                emailInputForgot.classList.add('is-invalid');
                return;
            }
            submitForgot();
        });

        if (resendBtnForgot) resendBtnForgot.addEventListener('click', submitForgot);
    }
})();

(function () {
    // Character counter for notes
    var textareas = document.querySelectorAll('.meal-note');
    for (var i = 0; i < textareas.length; i++) {
        textareas[i].addEventListener('input', function() {
            var mealId = this.getAttribute('data-meal-id');
            var counter = document.getElementById('charcount_' + mealId);
            if (counter) counter.textContent = this.value.length;
        });
    }

    // Update note button handler
    var buttons = document.querySelectorAll('.update-note-btn');
    for (var j = 0; j < buttons.length; j++) {
        buttons[j].addEventListener('click', function() {
            var self = this;
            var mealId = self.getAttribute('data-meal-id');
            var noteInput = document.getElementById('note_' + mealId);
            var noteText = noteInput ? noteInput.value : '';
            var actionUrl = self.getAttribute('data-action-url');

            if (!actionUrl) {
                console.error('Action URL not found on button');
                return;
            }

            fetch(actionUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: 'mealId=' + encodeURIComponent(mealId) + '&note=' + encodeURIComponent(noteText)
            })
            .then(function(response) { return response.json(); })
            .then(function(data) {
                if (data.success) {
                    alert('Нотатка збережена!');
                } else {
                    alert(data.error || 'Помилка при збереженні нотатки');
                }
            })
            ['catch'](function(error) {
                console.error('Error:', error);
                alert('Помилка при збереженні нотатки');
            });
        });
    }
})();

(function () {
    var form     = document.getElementById('sf-fi-form');
    var skeleton = document.getElementById('sf-fi-skeleton');
    var results  = document.getElementById('sf-fi-results');
    var btn      = document.getElementById('sf-fi-btn');
    var btnText  = document.getElementById('sf-fi-btn-text');
    var btnSpin  = document.getElementById('sf-fi-btn-spinner');

    if (!form) return;

    form.addEventListener('submit', function (e) {
        e.preventDefault();

        var action = form.getAttribute('action') || location.href;
        var url = new URL(action, location.origin);
        var formData = new FormData(form);
        
        var entries = formData.entries();
        var entry = entries.next();
        while (!entry.done) {
            var k = entry.value[0];
            var v = entry.value[1];
            if (v) url.searchParams.set(k, v);
            else   url.searchParams.delete(k);
            entry = entries.next();
        }

        if (results) results.classList.add('d-none');
        if (skeleton) skeleton.classList.remove('d-none');
        if (btn) btn.disabled = true;
        if (btnText) btnText.classList.add('d-none');
        if (btnSpin) btnSpin.classList.remove('d-none');

        history.pushState(null, '', url.toString());

        fetch(url.toString(), { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
            .then(function(r) { return r.text(); })
            .then(function(html) {
                var parser = new DOMParser();
                var doc   = parser.parseFromString(html, 'text/html');
                var fresh = doc.getElementById('sf-fi-results');
                if (fresh && results) results.innerHTML = fresh.innerHTML;
            })
            ['catch'](function() { location.href = url.toString(); })
            ['finally'](function() {
                if (skeleton) skeleton.classList.add('d-none');
                if (results) results.classList.remove('d-none');
                if (btn) btn.disabled = false;
                if (btnText) btnText.classList.remove('d-none');
                if (btnSpin) btnSpin.classList.add('d-none');
            });
    });
})();

(function () {
    // ── Категорія ─────────────────────────────────────────────────────────
    var catInput = document.getElementById('categoryInput');
    if (catInput) {
        var catBtns = document.querySelectorAll('.sf-cat-btn');
        for (var i = 0; i < catBtns.length; i++) {
            catBtns[i].addEventListener('click', function () {
                for (var j = 0; j < catBtns.length; j++) {
                    catBtns[j].classList.remove('active');
                }
                this.classList.add('active');
                catInput.value = this.getAttribute('data-value');
            });
        }
    }

    // ── Попередній перегляд порції ────────────────────────────────────────
    var inpCal  = document.getElementById('inp_cal');
    var inpProt = document.getElementById('inp_prot');
    var inpFat  = document.getElementById('inp_fat');
    var inpCarb = document.getElementById('inp_carb');
    var inpG    = document.getElementById('previewGrams');

    var prevCal  = document.getElementById('prev_cal');
    var prevProt = document.getElementById('prev_prot');
    var prevFat  = document.getElementById('prev_fat');
    var prevCarb = document.getElementById('prev_carb');

    function calcPreview() {
        if (!inpG || !prevCal) return;
        
        var g    = parseFloat(inpG.value)    || 0;
        var cal  = parseFloat(inpCal ? inpCal.value : 0)  || 0;
        var prot = parseFloat(inpProt ? inpProt.value : 0) || 0;
        var fat  = parseFloat(inpFat ? inpFat.value : 0)  || 0;
        var carb = parseFloat(inpCarb ? inpCarb.value : 0) || 0;
        var k = g / 100;
        
        if (prevCal) prevCal.textContent  = g ? (cal  * k).toFixed(0) : '–';
        if (prevProt) prevProt.textContent = g ? (prot * k).toFixed(1) : '–';
        if (prevFat) prevFat.textContent  = g ? (fat  * k).toFixed(1) : '–';
        if (prevCarb) prevCarb.textContent = g ? (carb * k).toFixed(1) : '–';
    }

    if (inpG) {
        var els = [inpCal, inpProt, inpFat, inpCarb, inpG];
        for (var k = 0; k < els.length; k++) {
            if (els[k]) els[k].addEventListener('input', calcPreview);
        }
        calcPreview();
    }
})();

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initAddToLog();
    });

    function initAddToLog() {
        var qtyEl = document.getElementById('sf-atl-qty');
        if (!qtyEl) return;

        var recalc = function () {
            var kcalEl = document.getElementById('sf-atl-calc-kcal');
            if (!kcalEl) return;

            var kcalPer100 = parseFloat(kcalEl.getAttribute('data-per100')) || 0;
            var protEl = document.getElementById('sf-atl-calc-protein');
            var fatEl = document.getElementById('sf-atl-calc-fat');
            var carbEl = document.getElementById('sf-atl-calc-carbs');

            var protPer100 = protEl ? (parseFloat(protEl.getAttribute('data-per100')) || 0) : 0;
            var fatPer100 = fatEl ? (parseFloat(fatEl.getAttribute('data-per100')) || 0) : 0;
            var carbPer100 = carbEl ? (parseFloat(carbEl.getAttribute('data-per100')) || 0) : 0;

            var qty = parseFloat(qtyEl.value) || 0;
            var factor = qty / 100;

            kcalEl.textContent = (kcalPer100 * factor).toFixed(0);
            if (protEl) protEl.textContent = (protPer100 * factor).toFixed(1);
            if (fatEl) fatEl.textContent = (fatPer100 * factor).toFixed(1);
            if (carbEl) carbEl.textContent = (carbPer100 * factor).toFixed(1);
        };

        qtyEl.addEventListener('input', recalc);
        
        recalc();

        var searchEl = document.getElementById('sf-atl-search');
        var resultsEl = document.getElementById('sf-atl-results');
        var hintEl = document.getElementById('sf-atl-hint');
        var searchTimer;

        if (searchEl) {
            searchEl.addEventListener('input', function () {
                clearTimeout(searchTimer);
                var q = searchEl.value.trim();
                if (q.length < 2) {
                    resultsEl.innerHTML = '';
                    if (hintEl) resultsEl.appendChild(hintEl);
                    return;
                }
                searchTimer = setTimeout(function () {
                    fetch('/Food/SearchJson?q=' + encodeURIComponent(q))
                        .then(function(r) { return r.json(); })
                        .then(function(data) { renderResults(data, resultsEl); })
                        .catch(function() { resultsEl.innerHTML = '<div class="text-danger small text-center py-3">Помилка пошуку</div>'; });
                }, 300);
            });
        }
    }

    function renderResults(items, resultsEl) {
        resultsEl.innerHTML = '';
        if (!items || items.length === 0) {
            resultsEl.innerHTML = '<div class="text-muted small text-center py-3">Нічого не знайдено</div>';
            return;
        }
        items.forEach(function(f) {
            var btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'list-group-item list-group-item-action d-flex justify-content-between align-items-center';
            
            var category = f.category ? f.category : '';
            btn.innerHTML = '<div>' +
                  '<div class="fw-semibold">' + escHtml(f.name) + '</div>' +
                  '<small class="text-muted">' + Math.round(f.caloriesPer100g) + ' ккал / 100г</small>' +
                '</div>' +
                '<span class="badge bg-primary-subtle text-primary rounded-pill">' + escHtml(category) + '</span>';
            
            btn.addEventListener('click', function () {
                selectFood(f);
                var listItems = resultsEl.querySelectorAll('.list-group-item');
                for (var i = 0; i < listItems.length; i++) {
                    listItems[i].classList.remove('active');
                }
                btn.classList.add('active');
            });
            resultsEl.appendChild(btn);
        });
    }

    function selectFood(food) {
        var kcalEl = document.getElementById('sf-atl-calc-kcal');
        if (!kcalEl) return;

        kcalEl.setAttribute('data-per100', food.caloriesPer100g);
        document.getElementById('sf-atl-calc-protein').setAttribute('data-per100', food.proteinPer100g);
        document.getElementById('sf-atl-calc-fat').setAttribute('data-per100', food.fatPer100g);
        document.getElementById('sf-atl-calc-carbs').setAttribute('data-per100', food.carbsPer100g);

        document.getElementById('sf-atl-foodId').value = food.id;
        document.getElementById('sf-atl-name').textContent = food.name;
        document.getElementById('sf-atl-category').textContent = food.category ? food.category : '';
        document.getElementById('sf-atl-kcal').textContent = Math.round(food.caloriesPer100g);
        document.getElementById('sf-atl-protein').textContent = food.proteinPer100g.toFixed(1);
        document.getElementById('sf-atl-fat').textContent = food.fatPer100g.toFixed(1);
        document.getElementById('sf-atl-carbs').textContent = food.carbsPer100g.toFixed(1);

        document.getElementById('sf-atl-no-selection').classList.add('d-none');
        document.getElementById('sf-atl-form-container').classList.remove('d-none');
        
        var qtyEl = document.getElementById('sf-atl-qty');
        if (qtyEl) {
            qtyEl.value = 100;
            qtyEl.dispatchEvent(new Event('input'));
        }
    }

    function escHtml(str) {
        return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

})();

(function () {
    'use strict';
    
    document.addEventListener('DOMContentLoaded', function () {
        var form = document.getElementById('sf-bc-form');
        var btn = document.getElementById('sf-bc-btn');
        var btnText = document.getElementById('sf-bc-btn-text');
        var btnSpin = document.getElementById('sf-bc-btn-spin');
        
        if (!form || !btn) return;
        
        form.addEventListener('submit', function () {
            btn.disabled = true;
            if (btnText) btnText.classList.add('d-none');
            if (btnSpin) btnSpin.classList.remove('d-none');
        });
    });
})();

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initExport();
    });

    function initExport() {
        var radios = document.querySelectorAll('.export-format-option input[type="radio"]');
        for (var i = 0; i < radios.length; i++) {
            radios[i].addEventListener('change', function() {
                var options = document.querySelectorAll('.export-format-option');
                for (var j = 0; j < options.length; j++) {
                    options[j].classList.remove('active');
                }
                this.closest('.export-format-option').classList.add('active');
            });
        }

        var fromInput = document.querySelector('input[name="From"]');
        var toInput = document.querySelector('input[name="To"]');
        var info = document.getElementById('recordCountInfo');

        var updateCount = function () {
            var fromDate = fromInput ? fromInput.value : null;
            var toDate = toInput ? toInput.value : null;

            if (fromDate && toDate && info) {
                fetch('/export/record-count?from=' + encodeURIComponent(fromDate) + '&to=' + encodeURIComponent(toDate))
                    .then(function(response) { 
                        if (response.ok) return response.json();
                        throw new Error('Network response was not ok');
                    })
                    .then(function(data) {
                        if (data.count > 0) {
                            if (data.count > 10000) {
                                info.className = 'alert alert-warning mt-3 small';
                                info.innerHTML = '<i class="bi bi-exclamation-triangle"></i> <strong>Велика кількість записів (' + data.count + ')!</strong> Файл може бути великим (орієнтовно ' + Math.round(data.count / 1000) + 'MB). Це може зайняти деякий час.';
                            } else {
                                info.className = 'alert alert-success mt-3 small';
                                info.innerHTML = '<i class="bi bi-check-circle"></i> Буде експортовано <strong>' + data.count + '</strong> записів';
                            }
                        } else {
                            info.className = 'alert alert-info mt-3 small';
                            info.innerHTML = '<i class="bi bi-info-circle"></i> За обраним періодом немає записів';
                        }
                    })
                    .catch(function(error) {
                        console.error('Error fetching record count:', error);
                    });
            }
        };

        if (fromInput) fromInput.addEventListener('change', updateCount);
        if (toInput) toInput.addEventListener('change', updateCount);

        if (fromInput && fromInput.value && toInput && toInput.value) {
            updateCount();
        }
    }
})();

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initAdminUsers();
    });

    function initAdminUsers() {
        var timeout = null;
        var emailInput = document.getElementById('emailSearchInput');
        var autocompleteList = document.getElementById('emailAutocompleteList');
        var searchForm = document.getElementById('searchForm');
        
        if (!emailInput || !autocompleteList || !searchForm) return;

        document.addEventListener('click', function(e) {
            if (e.target !== emailInput && e.target !== autocompleteList) {
                autocompleteList.classList.add('d-none');
            }
        });

        emailInput.addEventListener('input', function() {
            clearTimeout(timeout);
            var query = emailInput.value.trim();
            
            if (query.length < 2) {
                autocompleteList.classList.add('d-none');
                autocompleteList.innerHTML = '';
                
                if (query.length === 0) {
                    timeout = setTimeout(function() { searchForm.submit(); }, 800);
                }
                return;
            }

            timeout = setTimeout(function() {
                fetch('/admin/users/autocomplete?q=' + encodeURIComponent(query))
                    .then(function(response) { return response.json(); })
                    .then(function(data) {
                        autocompleteList.innerHTML = '';
                        
                        if (data && data.length > 0) {
                            for (var i = 0; i < data.length; i++) {
                                (function(email) {
                                    var li = document.createElement('li');
                                    li.className = 'list-group-item list-group-item-action cursor-pointer';
                                    li.textContent = email;
                                    li.style.cursor = 'pointer';
                                    
                                    li.addEventListener('click', function() {
                                        emailInput.value = email;
                                        autocompleteList.classList.add('d-none');
                                        searchForm.submit();
                                    });
                                    
                                    autocompleteList.appendChild(li);
                                })(data[i]);
                            }
                            autocompleteList.classList.remove('d-none');
                        } else {
                            autocompleteList.classList.add('d-none');
                        }
                    })
                    .catch(function(err) { console.error('Autocomplete error:', err); });
            }, 300);
        });
    }
})();

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initResetPassword();
    });

    function initResetPassword() {
        var form = document.getElementById('resetForm');
        var passInput = document.getElementById('newPassword');
        var confInput = document.getElementById('confirmPassword');
        var submitBtn = document.getElementById('submitBtn');

        if (!passInput || !confInput || !submitBtn) return;

        var reqLength = document.getElementById('reqLength');
        var reqUpper = document.getElementById('reqUpper');
        var reqLower = document.getElementById('reqLower');
        var reqDigit = document.getElementById('reqDigit');

        var setReq = function (el, valid) {
            if (!el) return;
            var icon = el.querySelector('i');
            if (valid) {
                if (icon) {
                    icon.classList.remove('bi-x-circle', 'text-danger');
                    icon.classList.add('bi-check-circle-fill', 'text-success');
                }
                el.classList.remove('text-muted');
                el.classList.add('text-success');
            } else {
                if (icon) {
                    icon.classList.remove('bi-check-circle-fill', 'text-success');
                    icon.classList.add('bi-x-circle', 'text-danger');
                }
                el.classList.remove('text-success');
                el.classList.add('text-muted');
            }
        };

        var validatePassword = function () {
            var val = passInput.value;
            var lenValid = val.length >= 8;
            var upperValid = /[A-Z]/.test(val);
            var lowerValid = /[a-z]/.test(val);
            var digitValid = /[0-9]/.test(val);

            setReq(reqLength, lenValid);
            setReq(reqUpper, upperValid);
            setReq(reqLower, lowerValid);
            setReq(reqDigit, digitValid);

            return lenValid && upperValid && lowerValid && digitValid;
        };

        var validateMatch = function () {
            if (!confInput.value) {
                confInput.classList.remove('is-invalid', 'is-valid');
                return false;
            }
            if (passInput.value === confInput.value) {
                confInput.classList.remove('is-invalid');
                confInput.classList.add('is-valid');
                return true;
            } else {
                confInput.classList.add('is-invalid');
                confInput.classList.remove('is-valid');
                return false;
            }
        };

        var checkAll = function () {
            var isValidPass = validatePassword();
            var isValidMatch = validateMatch();
            
            if (isValidPass && isValidMatch) {
                submitBtn.classList.remove('disabled');
            } else {
                submitBtn.classList.add('disabled');
            }
        };

        passInput.addEventListener('input', checkAll);
        confInput.addEventListener('input', checkAll);
        
        checkAll();
    }
})();
